{
  "requirements": [
    {
      "text": "The system shall continuously monitor the health and diagnostic status of all primary sensors (forward‑facing camera, radar, ultrasonic) and, upon detection of a fault or degradation beyond defined thresholds, immediately transition to a safe state and notify the driver."
    },
    {
      "text": "The system shall employ a multimodal driver‑engagement monitor (steering torque, hands‑on‑wheel detection, and driver‑facing camera or eye‑tracking) and shall disengage Autopilot within 0.5 seconds if the driver is not actively supervising the vehicle."
    },
    {
      "text": "The system shall guarantee that control is transferred back to the driver within 0.5 seconds of Autopilot disengagement, with an audible and visual alert that persists until driver control is confirmed."
    },
    {
      "text": "The system shall only engage Autosteer when lane‑marking detection confidence exceeds a predefined safety threshold; if confidence drops, Autosteer shall automatically disengage and alert the driver."
    },
    {
      "text": "The system shall limit the maximum speed while Autopilot is active based on road type, weather conditions, and current sensor confidence levels, and shall reduce speed automatically when any of these factors degrade."
    },
    {
      "text": "The system shall integrate Forward Collision Warning and Automatic Emergency Braking with Autosteer so that, if Autosteer fails to avoid an imminent collision, emergency braking is applied without driver input."
    },
    {
      "text": "The system shall provide redundant lane‑keeping logic using at least two independent sensor modalities (e.g., camera and radar) and shall cross‑validate their outputs before applying steering commands."
    },
    {
      "text": "The system shall detect operation outside its Operational Design Domain (e.g., heavy rain, fog, low visibility, poorly marked roads) and shall immediately alert the driver and deactivate Autopilot functions."
    },
    {
      "text": "The system shall implement authenticated, integrity‑checked software update mechanisms and protect all internal communications against unauthorized access or tampering."
    },
    {
      "text": "The system shall record, in a tamper‑evident log, all sensor data, driver inputs, system states, and control commands for at least 30 seconds before and after any Autopilot disengagement or collision event."
    }
  ]
}
